let portfolioShareDraft=null,lastPortfolioShare=null;
function portfolioSharingButtons(){return ['s1','s2'].includes(uid)?btn('Prepare private CV','openPrivatePortfolioExport(true)')+btn('Edit my CV declarations','openCVDeclarations()')+btn('Preview private achievement export','openPrivatePortfolioExport()')+btn('Preview & share selected achievements','openPortfolioShareBuilder()','primary')+btn('Manage share links','managePortfolioShares()'):''}
function openPortfolioShareBuilder(){if(!sharedReady||sharedBusy)return toast('Wait for the shared workspace.');let eligible=db.projects.filter(p=>verifiedActivity(p)&&successfulParticipant(p,uid)&&deliveryIndividualReady(p,uid));if(!eligible.length)return toast('Complete and verify an individual achievement first.');modal(`<h2>Create a portfolio presentation</h2><p>Select exactly what to disclose. Nothing is shared until you review the preview and grant consent.</p><form onsubmit="previewPortfolioShare(event)"><label>Presentation purpose<select name="purpose">${['EMPLOYMENT','LEADERSHIP','TECHNICAL','RESEARCH','ENTREPRENEURSHIP','SDG_IMPACT'].map(v=>`<option>${v}</option>`).join('')}</select></label><fieldset><legend>Verified achievements</legend>${eligible.map(p=>`<label><input type="checkbox" name="project" value="${p.id}"> ${esc(p.title)} · ${esc(p.programme)}</label>`).join('')}</fieldset><label><input type="checkbox" name="hours" value="yes"> Include verified attendance and contribution hours as separate measures</label><label>Link expires after<select name="days"><option value="7">7 days</option><option value="30">30 days</option><option value="90">90 days</option></select></label><p>Audience: anyone with the link, without sign-in. Purpose: review selected verified achievements. Name, activity title, programme, type and SDG alignment will be shown. No grades, reflections, files or contact information are included.</p><button class="primary">Review exact public content</button> <button type="button" onclick="closeModal()">Cancel</button></form>`)}
function portfolioPreviewHTML(p){return `<div class="notice"><strong>${esc(p.studentName)}</strong> · ${esc(p.purpose)}<br>Audience: anyone with the link · Expiry: ${p.days} days from creation.</div>${p.items.map(i=>`<div class="card"><h3>${esc(i.title)}</h3><p>${esc(i.programme)} · ${esc(i.type)} · SDG ${esc(i.sdg)}</p><p>${esc(i.verification)}</p>${p.includeHours?`<p>Verified attendance ${(i.attendanceMinutes/60).toFixed(2)} h · Verified contribution ${(i.contributionMinutes/60).toFixed(2)} h (separate measures)</p>`:''}</div>`).join('')}`}
async function previewPortfolioShare(event){event.preventDefault();if(sharedBusy)return;let f=new FormData(event.target),body={mode:'preview',actor:sharedActor,revision:sharedRevision,projectIds:f.getAll('project'),purpose:f.get('purpose'),includeHours:f.get('hours')==='yes',days:Number(f.get('days'))};lockShared(true);try{let r=await sharedFetch('/api/portfolio-shares',body);portfolioShareDraft={...body,mode:'create',previewDigest:r.previewDigest};modal(`<h2>Review your public portfolio content</h2>${portfolioPreviewHTML(r.preview)}<p>Public view only. No search listing is requested. People who have the link may save copies; revocation stops future access to this view.</p><form onsubmit="confirmPortfolioShare(event)"><label><input type="checkbox" name="consent" value="yes" required> I consent to share exactly these item versions and fields with anyone holding the link for this purpose and duration.</label><button class="primary">Grant consent & create expiring link</button> <button type="button" onclick="closeModal()">Cancel</button></form>`)}catch(e){toast(e.message)}finally{lockShared(false)}}
async function confirmPortfolioShare(event){event.preventDefault();if(sharedBusy||!portfolioShareDraft||new FormData(event.target).get('consent')!=='yes')return;lockShared(true);try{let r=await sharedFetch('/api/portfolio-shares',{...portfolioShareDraft,consent:true});applyShared(r);portfolioShareDraft=null;lastPortfolioShare={url:r.url,qrSvg:r.qrSvg};closeModal();modal(`<h2>Expiring portfolio link created</h2><p>Copy or save this link now. It is shown only at creation; if lost, revoke it and create another.</p><label>Share URL<input readonly id="portfolio-share-url" value="${esc(r.url)}" onclick="this.select()"></label><p><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Open the public view</a></p><img alt="QR code for the expiring portfolio link" width="256" height="256" src="data:image/svg+xml,${encodeURIComponent(r.qrSvg)}"><p>Revoking the link also invalidates this QR code. Existing official records are retained.</p><div class="buttons">${btn('Copy link','copyPortfolioShareLink()')}${btn('Save QR code','savePortfolioShareQR()')}${btn('Close','closeModal()')}</div>`)}catch(e){toast(e.message)}finally{lockShared(false)}}
async function copyPortfolioShareLink(){if(!lastPortfolioShare)return;try{await navigator.clipboard.writeText(lastPortfolioShare.url);toast('Link copied.')}catch{let n=document.querySelector('#portfolio-share-url');n?.select();toast('Select and copy the displayed link.')}}
function savePortfolioShareQR(){if(!lastPortfolioShare)return;let a=document.createElement('a');a.href='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(lastPortfolioShare.qrSvg);a.download='KCC360-portfolio-share-QR.svg';a.click()}
async function managePortfolioShares(){if(sharedBusy)return;lockShared(true);try{let r=await sharedFetch('/api/portfolio-shares');if(r.actor!==sharedActor||r.revision!==sharedRevision)throw Error('The account or records changed. Refresh shared data first.');modal(`<h2>Your share links</h2><p>These records preserve audience, purpose, selected versions, grant time and expiry. Raw links are shown only at creation. Official records remain private unless included in a consented active link.</p>${r.shares.map(s=>`<div class="card" style="margin:12px 0"><h3>${s.kind==='REFLECTION'?'Reflection':esc(s.purpose)}</h3>${pill(s.status)}<p>${s.items.map(esc).join('<br>')}</p><p class="meta">Reference PF-${esc(s.id)} · Created ${esc(eventTime(s.createdAt))} · Expires ${esc(eventTime(s.expiresAt))}${s.revokedAt?' · Revoked '+esc(eventTime(s.revokedAt)):''}</p>${s.kind==='REFLECTION'&&s.responses?reflectionLinkResponsesHTML(s.responses):''}${s.status!=='REVOKED'?btn('Revoke link & QR',`revokePortfolioShare('${s.id}')`):''}</div>`).join('')||'<p>No share links have been created. Your portfolio is private by default.</p>'}${btn('Close','closeModal()')}`)}catch(e){toast(e.message)}finally{lockShared(false)}}
async function revokePortfolioShare(id){if(sharedBusy)return;lockShared(true);try{let r=await sharedFetch('/api/portfolio-shares',{mode:'revoke',id,actor:sharedActor,revision:sharedRevision});applyShared(r);lastPortfolioShare=null;closeModal();toast(r.message)}catch(e){toast(e.message)}finally{lockShared(false)}}

let privatePortfolioExportDraft=null,privatePortfolioExportSequence=0;
function cancelPrivatePortfolioExport(){privatePortfolioExportSequence++;privatePortfolioExportDraft=null;closeModal()}
function privatePortfolioExportReady(){return sharedReady&&!sharedBusy&&['s1','s2'].includes(uid)&&uid===sharedActor}
function openPrivatePortfolioExport(cv=false){if(!privatePortfolioExportReady())return toast('Select your own current student account and wait for the workspace.');privatePortfolioExportSequence++;privatePortfolioExportDraft=null;const eligible=db.projects.filter(p=>activityControlActive(p)&&verifiedActivity(p)&&successfulParticipant(p,uid)&&deliveryIndividualReady(p,uid));if(!cv&&!eligible.length)return toast('Complete and verify an individual achievement before preparing a private export.');modal(`<h2>${cv?'Prepare a private CV':'Prepare a private achievement export'}</h2><p>Select the verified achievements to include. This private preview creates no public link and grants no sharing consent.</p>${cv?'<p>Select saved student-declared sections and verified achievements. No public link is created. Declarations are not verified by KCC.</p>':'<p>Achievement summary only; academic history, experience and certificate sections are not included. This is not a complete CV or official credential.</p>'}<form id="private-portfolio-export-form" onsubmit="previewPrivatePortfolioExport(event)">${cv?`<input type="hidden" name="cv" value="yes"><fieldset><legend>Optional student-declared sections</legend>${Object.entries(cvDeclarationFields).filter(([k])=>db.cvDeclarations?.[uid]?.content?.[k]?.trim()).map(([k,title])=>`<label><input type="checkbox" name="section" value="${k}"> ${title} · Student-declared</label>`).join('')||'<p>No saved declarations. Use Edit my CV declarations first.</p>'}</fieldset>`:''}${cv?`<fieldset><legend>Optional issued demonstration certificates (up to 20)</legend>${eligible.filter(p=>p.certs?.[uid]?.status==='VALID'&&p.certs[uid].recipient===uid&&p.evaluations?.[uid]?.certificateEligible!==false&&(!p.certs[uid].evaluationVersion||p.certs[uid].evaluationVersion===(p.evaluations?.[uid]?.version||1))).map(p=>`<label><input type="checkbox" name="certificate" value="${esc(p.certs[uid].id)}"> ${esc(p.certs[uid].projectTitle||p.title)} · ${esc(p.certs[uid].id)} · v${esc(p.certs[uid].version||1)}</label>`).join('')||'<p>No current eligible issued certificates.</p>'}</fieldset>`:''}<fieldset><legend>${cv?'Optional verified achievements (up to 20)':'Select 1–20 verified achievements'}</legend>${eligible.map(p=>`<label><input type="checkbox" name="project" value="${esc(p.id)}"> ${esc(p.title)} · ${esc(p.programme)}</label>`).join('')}</fieldset><label><input type="checkbox" name="hours" value="yes"> Include verified attendance and contribution hours as separate measures</label><button class="primary">Review private content</button> <button type="button" onclick="cancelPrivatePortfolioExport()">Cancel</button></form>`)}
function privatePortfolioExportPreviewHTML(p){if(p?.schema!=='PRIVATE_VERIFIED_ACHIEVEMENTS_PILOT_1'||p.audience!=='OWNER_PRIVATE'||!Array.isArray(p.items))throw Error('Private preview unavailable. Refresh and try again.');return `<section class="notice"><strong>${esc(p.studentName)}</strong><p>Private · ${esc(p.coverage)}</p><p>Generated ${esc(eventTime(p.generatedAt))}</p></section>${p.items.map(i=>`<article class="card"><h3>${esc(i.title)}</h3><p>${esc(i.programme)} · ${esc(i.type)} · SDG ${esc(i.sdg)}</p><p>${esc(i.verification)}</p>${p.includeHours?`<p>Verified attendance ${(i.attendanceMinutes/60).toFixed(2)} h · Verified contribution ${(i.contributionMinutes/60).toFixed(2)} h. These measures are not added together.</p>`:''}</article>`).join('')}`}
async function previewPrivatePortfolioExport(event){event.preventDefault();if(!privatePortfolioExportReady())return toast('Wait for your current student workspace.');const form=new FormData(event.target),body={mode:'preview',actor:sharedActor,revision:sharedRevision,projectIds:form.getAll('project'),includeHours:form.get('hours')==='yes',...(form.get('cv')==='yes'?{declarationSections:form.getAll('section'),certificateReferences:form.getAll('certificate')}:{})};if((!body.projectIds.length&&!body.declarationSections?.length&&!body.certificateReferences?.length)||body.certificateReferences?.length>20||body.projectIds.length>20||new Set(body.projectIds).size!==body.projectIds.length)return toast(body.declarationSections?'Select at least one saved declaration section or verified achievement, or an issued certificate (up to 20 achievements and 20 certificates).':'Select 1–20 distinct verified achievements.');const sequence=++privatePortfolioExportSequence,sourceForm=event.target;privatePortfolioExportDraft=null;lockShared(true);if(typeof sharedStatus==='function')sharedStatus(body.declarationSections?'Preparing private CV preview…':'Preparing private achievement preview…');try{const r=await sharedFetch('/api/portfolio-export',body);if(sequence!==privatePortfolioExportSequence||uid!==body.actor||sharedActor!==body.actor||sharedRevision!==body.revision||r.actor!==body.actor||r.revision!==body.revision||!$('#modal').open||document.querySelector('#private-portfolio-export-form')!==sourceForm)throw Error('The account, records or preview window changed. Open a fresh preview.');const preview=body.declarationSections?privateCVPreviewHTML(r.preview):privatePortfolioExportPreviewHTML(r.preview);privatePortfolioExportDraft={...body,mode:'print',previewDigest:r.previewDigest};modal(`<h2>${body.declarationSections?'Review your private CV':'Review your private achievement export'}</h2>${preview}<p>Opening the print view does not publish this information. The selected records are checked again first. A saved or printed copy cannot be recalled by withdrawing a public share link.</p><form id="private-portfolio-print-form" onsubmit="openPrivatePortfolioPrint(event)"><button class="primary">Open private print view</button> <button type="button" onclick="cancelPrivatePortfolioExport()">Cancel</button></form><p class="meta">In the new view, use your browser’s Print command or Save as PDF. ${body.declarationSections?'Declarations remain student-declared; selected achievements retain their verified source.':'This is a demonstration achievement summary.'}</p>`)}catch(error){toast(error.message)}finally{lockShared(false)}}
async function openPrivatePortfolioPrint(event){event.preventDefault();if(!privatePortfolioExportReady()||!privatePortfolioExportDraft)return toast('Preview the current private selection first.');const draft=privatePortfolioExportDraft;if(draft.actor!==sharedActor||draft.revision!==sharedRevision)return toast('The account or records changed. Preview again.');let popup;try{popup=window.open('about:blank','_blank');if(!popup)return toast('Allow the private print window, then try again.');popup.opener=null;popup.document.open();popup.document.write('<!doctype html><html lang="en"><title>Preparing private view</title><p>Preparing the private achievement view…</p></html>');popup.document.close()}catch{try{popup?.close()}catch{}return toast('The private print window could not be opened.')}lockShared(true);if(typeof sharedStatus==='function')sharedStatus('Preparing private print view…');try{const response=await fetch('/api/portfolio-export',{method:'POST',credentials:'same-origin',cache:'no-store',redirect:'error',headers:{'Content-Type':'application/json'},body:JSON.stringify(draft)});if(!response.ok){let message='Private print view unavailable. Refresh and preview again.';try{const error=await response.json();message=error.error||message}catch{}throw Error(message)}if(!response.headers.get('Content-Type')?.startsWith('text/html')||response.headers.get('X-KCC360-Export')!=='private-achievements-print-v1')throw Error('Private print response unavailable. Refresh and try again.');const html=await response.text();if(privatePortfolioExportDraft!==draft||uid!==draft.actor||sharedActor!==draft.actor||sharedRevision!==draft.revision||!$('#modal').open||!document.querySelector('#private-portfolio-print-form'))throw Error('The account, records or preview window changed. Preview again.');if(popup.closed)throw Error('The private print window was closed. Open it again if needed.');popup.document.open();popup.document.write(html);popup.document.close();toast('Private view opened. Use the browser Print command or Save as PDF.')}catch(error){try{if(!popup.closed)popup.close()}catch{}toast(error.message)}finally{lockShared(false)}}

const cvDeclarationFields={summary:'Personal summary',education:'Education and school history',training:'External training and certificates',skills:'Professional skills and languages',experience:'External work, internships and volunteering'};
function openCVDeclarations(){if(!privatePortfolioExportReady())return toast('Select your own current student account and wait for the workspace.');let r=db.cvDeclarations?.[uid];modal(`<h2>My CV declarations</h2><p>Private student-declared information. No KCC approval is required. These statements do not become verified portfolio records. Leave a section blank to remove its contents.</p><form onsubmit="saveCVDeclarations(event)">${Object.entries(cvDeclarationFields).map(([k,title])=>`<label>${title}<textarea name="${k}" maxlength="2000">${esc(r?.content?.[k]||'')}</textarea></label>`).join('')}<p>Include institution/provider, qualification or role, and dates where relevant. Do not enter passwords, government identifiers or another person's private information.</p><button class="primary">Save private declarations</button> <button type="button" onclick="closeModal()">Cancel</button></form>`)}
function saveCVDeclarations(event){event.preventDefault();if(!['s1','s2'].includes(uid))return toast('Only students can update their own CV declarations.');const f=Object.fromEntries(new FormData(event.target));if(Object.keys(f).some(k=>!Object.hasOwn(cvDeclarationFields,k))||Object.keys(cvDeclarationFields).some(k=>typeof f[k]!=='string'||f[k].length>2000||/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/.test(f[k])))return toast('Use the five declaration sections, with at most 2,000 characters in each.');const content=Object.fromEntries(Object.keys(cvDeclarationFields).map(k=>[k,f[k].trim()]));db.cvDeclarations??={};const previous=db.cvDeclarations[uid];if(JSON.stringify(previous?.content)===JSON.stringify(content))return toast('No declaration changes to save.');db.cvDeclarations[uid]={version:(previous?.version||0)+1,classification:'STUDENT_DECLARED',updatedAt:new Date().toISOString(),content};closeModal();render();toast('Private CV declarations saved. Verified portfolio records are unchanged.')}

function privateCVPreviewHTML(p){if(p?.schema!=='PRIVATE_CV_1'||p.audience!=='OWNER_PRIVATE'||!Array.isArray(p.declarations)||!Array.isArray(p.items))throw Error('Private CV preview unavailable.');return `<div class="notice"><strong>${esc(p.studentName)}</strong><p>Private demonstration CV · Generated ${esc(eventTime(p.generatedAt))}</p><p>This CV is not an official KCC credential. Academic results and official credential documents are not included.</p></div>${p.declarations.map(d=>`<article class="card"><h3>${esc(d.title)}</h3><p>Student-declared · Not verified by KCC</p><p style="white-space:pre-wrap">${esc(d.text)}</p></article>`).join('')}${(p.certificates||[]).map(c=>`<article class="card"><h3>${esc(c.title)}</h3><p>${esc(c.verification)}</p><p>Issuer: ${esc(c.issuer)} · Issued ${esc(c.issuedAt.slice(0,10))}</p><p>Reference: ${esc(c.reference)} · Version ${esc(c.version)} · ${esc(c.status)}</p></article>`).join('')}${p.items.length?'<h3>Verified portfolio achievements</h3>'+privatePortfolioExportPreviewHTML({...p,schema:'PRIVATE_VERIFIED_ACHIEVEMENTS_PILOT_1',coverage:'Selected verified achievements'}):''}`}

function reflectionLinkResponsesHTML(rows){return `<section><h4>Reader acknowledgments (${rows.length})</h4><p>Link visitor identities and relationships are unverified. Responses are private to you and do not affect academic evaluation.</p>${rows.map(r=>`<article class="notice"><strong>${r.response==='APPRECIATED'?'Read and appreciated':'Read acknowledgment'}</strong><p>${r.name?esc(r.name)+' · ':''}${esc(({GUARDIAN:'Parent / guardian',FAMILY:'Family member',OTHER:'Other reader'})[r.relationship]||'Reader')} (self-declared, unverified)</p><p>Reflection v${esc(r.reflectionVersion)} · ${esc(eventTime(r.receivedAt))}</p>${r.message?'<p style="white-space:pre-wrap;overflow-wrap:anywhere">'+esc(r.message)+'</p>':''}</article>`).join('')||'<p>No acknowledgments received.</p>'}</section>`}
